// TH14 v1.00b Extra（st07.ecl.txt）MainSub02 / 源行 690-732；依赖 ECir00 14-47、
// ECir00_at 49-82、MainSub02b 734-752。Extra 取源 O 位，仅实现 rank 4。
// 弹型复制自 transcribe/th14/touhou-bullets.ecl：源 type4 对应目标同号 416，色号 8。
const TH14_BALL: int = 416;

const TIME_LIMIT: int = 2524;    // 120 开场 + 2400 排程/尾弹估计 + 4
const OPENING_BUFFER: int = 120;

// ECir00（源 14-47）：MIRROR 只决定 %A=±1；源用显式 *A 镜像，目标按坐标直接展开。
// 轨迹 = movePosRel(-192A,0) + moveBezierRel(120, 256A,-30, 160A,128, 0,0)
//      + wait(120) + moveBezierRel(120, 0,0, -220A,192, -200A,-228) + @ECir00_at()。
// 426 参数序为 (frames, tangent0, endpoint, tangent1)，切线针对归一化时间。
async sub ecir00(dir: int) {
    var d: fx = dir as fx;
    set_invuln(65535);              // 训练外壳：整段无敌，不模拟玩家 DPS
    set_hitbox(8fx);                // 源 setHitbox(16,16) -> 判定半径 8
    set_hurtbox(12fx);              // 源 setHurtbox(24,24) -> 半径 12

    // 源 34-35：入口即在 (-192A,0)，120 帧 Hermite 到 (160A,128)。
    hermite_start(0, -192fx * d, 160fx * d, 256fx * d, 0fx, 120);
    hermite_start(1, 0fx, 128fx, -30fx, 0fx, 120);
    for k in 0..120 {
        wait(1);
        move_to(0, hermite_value(0), hermite_value(1), EASE_LINEAR);
    }
    move_to(0, 160fx * d, 128fx, EASE_LINEAR);

    // 源 39-40：wait(120) 后启动第二段 Hermite，同时异步开始 ECir00_at。
    hermite_start(0, 160fx * d, -220fx * d, 0fx, -200fx * d, 120);
    hermite_start(1, 128fx, 192fx, 0fx, -228fx, 120);
    spawn ecir00_at();
    for j in 0..120 {
        wait(1);
        move_to(0, hermite_value(0), hermite_value(1), EASE_LINEAR);
    }
    move_to(0, -220fx * d, 192fx, EASE_LINEAR);

    // 源 41-45：goto 后 wait(1000) 无限循环，敌保持在场直到段结束。
    loop { wait(1000); }
}

// ECir00_at（源 49-82）：$B=1/$C=12 的两个 deci 循环各实际执行一轮。
async sub ecir00_at() {
    // 源 61：%A = %ANGLE_PLAYER，只取一次；12 条线依次 +0.523599rad(30°)。
    var base: angle = aim_player();
    var a: angle = base;
    for k in 0..12 {
        // 源 52/56/65-66：laserNew(0,0,128,0,14) + etAngle(A) + laserOn(0)。
        // Line 判定段原为 L/10..9L/10（L=128 -> 12.8..115.2），宽 14 -> 全宽 7。
        // 恒宽近似：按 lz_speed 以源 etSpeed 5 从近端长出并前进，laser_approx=true。
        var lz: int = laser(3, $self_x, $self_y, a, 115.2fx, 7fx, 0, 9999, 0);
        if lz != -1 {
            lz_start(lz, 12.8fx);
            lz_speed(lz, 5fx, 102.4fx);
        }
        a = a + 30deg;
    }

    // 源 70-77：模式3固定方向整周环，32 路 × 1 层、速 2；每颗出生退位移 4×初速 = 8px。
    var aim: angle = aim_player();
    for j in 0..32 {
        var b: angle = aim + ((j * 2048) as angle);   // 65536/32 = 2048
        _ = fire(TH14_BALL, 8,
                 $self_x - 8fx * cos(b), $self_y - 8fx * sin(b),
                 2fx, b, none, none);
    }
    wait(60);
}

// MainSub02b（源 734-752）：8 只镜像敌，间隔 40 帧；由同步/异步调用方决定起始时刻。
async sub mirror_series() {
    for i in 0..8 {
        _ = spawn_enemy(192fx, 0fx, 120, 0, 0, 0, ecir00(-1));
        if i != 7 { wait(40); }
    }
}

// MainSub02（源 690-732）：t=0 为入口行 690。8 只间隔 40 帧；wait(150) 后同步
// MainSub02b（镜像 8 只），再 wait(150)，异步 MainSub02b 与主侧第二组 8 只并行。
async sub pattern() {
    wait(OPENING_BUFFER);           // 训练开场缓冲：卡帧 120 对应源 t=0
    wait(40);
    for i in 0..8 {                 // 源 40..320，%A=+1
        _ = spawn_enemy(-192fx, 0fx, 120, 0, 0, 0, ecir00(1));
        if i != 7 { wait(40); }
    }
    wait(150);                      // 源 710：320 -> 470
    for i2 in 0..8 {                // 源 470..750，同步 MainSub02b，镜像 %A=-1
        _ = spawn_enemy(192fx, 0fx, 120, 0, 0, 0, ecir00(-1));
        if i2 != 7 { wait(40); }
    }
    wait(150);                      // 源 712：750 -> 900
    spawn mirror_series();          // 源 713：@MainSub02b() async（目标次帧首跑）
    wait(40);                       // 源 714：900 -> 940
    for i3 in 0..8 {                // 源 940..1220，主侧第二组 %A=+1
        _ = spawn_enemy(-192fx, 0fx, 120, 0, 0, 0, ecir00(1));
        if i3 != 7 { wait(40); }
    }
    wait(120);                      // 源 730：1220 -> 1340
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
